/// Exact f64 sum, min, max and every 613th value -- 613 is prime and coprime
/// with both 256 and 64, so the sample walks the whole grid rather than
/// landing on one column.
fn digest(a: &[f32]) -> (f64, f64, f64, Vec<f64>) {
    let mut sum = 0f64;
    let mut mn = f64::INFINITY;
    let mut mx = f64::NEG_INFINITY;
    for &v in a {
        let v = v as f64;
        sum += v;
        if v < mn { mn = v; }
        if v > mx { mx = v; }
    }
    (sum, mn, mx, a.iter().step_by(613).map(|&v| v as f64).collect())
}

/// The same brute-force nearest-seed Voronoi the harness uses. See this
/// file's header for why plate assignment is not `assign_plates` here.
fn brute_voronoi(seeds: &[cartalith_terrain::Plate], w: usize, h: usize) -> Vec<usize> {
    let mut id = vec![0usize; w * h];
    for y in 0..h {
        for x in 0..w {
            let mut best = 0usize;
            let mut bd = f64::INFINITY;
            for (p, s) in seeds.iter().enumerate() {
                let dx = s.x - x as f64;
                let dy = s.y - y as f64;
                let d = dx * dx + dy * dy;
                if d < bd { bd = d; best = p; }
            }
            id[y * w + x] = best;
        }
    }
    id
}
